import sys
import types

NS = types.SimpleNamespace
customer = NS(id="cus_77", orders={"1042"})


def refund_order(order_id, user):
    if order_id not in user.orders:
        raise PermissionError(f"Order {order_id} doesn't belong to this customer.")
    return f"Refunded order {order_id}: 49.00 USD to the original card."


REFUND_TOOL = {"name": "refund_order", "description": "Refunds an order.",
               "input_schema": {"type": "object"}}


def _create(*, model, max_tokens, messages, tools=None, **kwargs):
    last = messages[-1]["content"]
    if isinstance(last, list) and last and last[0].get("type") == "tool_result":
        res = last[0]
        text = ("I couldn't refund it: " if res.get("is_error") else "Done. ") + res["content"]
        return NS(content=[NS(type="text", text=text)], stop_reason="end_turn")
    blocks = [NS(type="text", text="I'll refund order 1042 now."),
              NS(type="tool_use", id="toolu_01", name="refund_order",
                 input={"order_id": "1042"})]
    return NS(content=blocks, stop_reason="tool_use")


class _Anthropic:
    def __init__(self, **kwargs):
        self.messages = NS(create=_create)


sys.modules["anthropic"] = NS(Anthropic=_Anthropic)
